"""Database models for agent write proposals and undo checkpoints."""

from datetime import datetime
from typing import Literal

from sqlmodel import Field, SQLModel

from app.models.user import utc_now

ProposalKind = Literal["create", "edit", "delete"]
ProposalStatus = Literal["pending", "accepted", "rejected", "applied", "undone", "stale"]


class Proposal(SQLModel, table=True):
    """A proposed change generated by the agent requiring review or auto-apply."""

    __tablename__ = "proposals"

    id: int | None = Field(default=None, primary_key=True)
    user_id: int = Field(index=True, foreign_key="users.id")
    repo_id: int = Field(index=True, foreign_key="repos.id")
    session_id: str | None = Field(default=None, index=True)
    kind: str = Field(index=True)  # "create" | "edit" | "delete"
    path: str = Field(index=True)
    old_content: str | None = Field(default=None)
    new_content: str | None = Field(default=None)
    base_hash: str | None = Field(default=None)
    rationale: str
    blast_radius_count: int | None = Field(default=None)
    status: str = Field(default="pending", index=True)
    # status: pending | accepted | rejected | applied | undone | stale
    created_at: datetime = Field(default_factory=utc_now)
    decided_at: datetime | None = Field(default=None)


class Checkpoint(SQLModel, table=True):
    """Snapshot of prior file state taken before applying a proposal, enabling clean undo."""

    __tablename__ = "checkpoints"

    id: int | None = Field(default=None, primary_key=True)
    proposal_id: int = Field(index=True, foreign_key="proposals.id")
    # JSON payload: {"existed": bool, "content": str, "is_new": bool, ...}
    previous: str
    created_at: datetime = Field(default_factory=utc_now)
